import AppKit
import CoreGraphics

/// Builds deterministic bitmaps so the imaging tests assert on known pixels
/// rather than on whatever a real screenshot happens to contain.
enum TestImages {
    /// A CGImage whose rows are generated by `row`, letting a test lay out a
    /// vertical pattern that stitching and overlap detection can be checked
    /// against.
    static func cgImage(
        width: Int,
        height: Int,
        row: (Int) -> (r: UInt8, g: UInt8, b: UInt8)
    ) -> CGImage {
        let bytesPerPixel = 4
        let bytesPerRow = width * bytesPerPixel
        var pixels = [UInt8](repeating: 255, count: bytesPerRow * height)

        for y in 0..<height {
            let color = row(y)
            for x in 0..<width {
                let offset = y * bytesPerRow + x * bytesPerPixel
                pixels[offset] = color.r
                pixels[offset + 1] = color.g
                pixels[offset + 2] = color.b
                pixels[offset + 3] = 255
            }
        }

        let context = CGContext(
            data: &pixels,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: bytesPerRow,
            space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        )!

        return context.makeImage()!
    }

    /// A single flat colour, for cases where only the dimensions matter.
    static func solidCGImage(
        width: Int,
        height: Int,
        r: UInt8 = 128,
        g: UInt8 = 128,
        b: UInt8 = 128
    ) -> CGImage {
        cgImage(width: width, height: height) { _ in (r, g, b) }
    }

    /// Every row a different shade, so any vertical offset is detectable.
    static func gradientCGImage(width: Int, height: Int, startingAt offset: Int = 0) -> CGImage {
        cgImage(width: width, height: height) { y in
            let value = UInt8((offset + y) % 256)
            return (value, value, value)
        }
    }

    static func nsImage(width: Int, height: Int) -> NSImage {
        let cgImage = solidCGImage(width: width, height: height)
        return NSImage(cgImage: cgImage, size: NSSize(width: width, height: height))
    }
}
